declare(strict_types=1);
function asUser(string $id,callable $fn){$old=$GLOBALS['service_user']??null;$GLOBALS['service_user']=$id;try{return $fn();}finally{if($old===null)unset($GLOBALS['service_user']);else $GLOBALS['service_user']=$old;}}
function botSettings(string $gid): array {$d=decode(file_get_contents(__DIR__.'/bot-defaults.json'));$r=entity('bot-settings-'.$gid,'bot_settings');return ['settings'=>['welcomer'=>array_replace($d['welcomer'],$r['settings']['welcomer']??[]),'moderator'=>array_replace($d['moderator'],$r['settings']['moderator']??[])],'revision'=>$r['revision']??0];}
function botAccount(string $kind,string $gid): array {
 $username='zdis_'.$kind.'_bot';$r=row('SELECT id FROM accounts WHERE username=?',[$username]);if($r){$u=account($r['id']);if(!($u['builtinBot']??false))fail(409,'Reserved bot username is already in use.');}else{$u=createUser(['username'=>$username,'email'=>$username.'@internal.invalid','password'=>'Z!'.bin2hex(random_bytes(24)),'displayName'=>$kind==='welcomer'?'Welcomer':'Moderator']);$u['builtinBot']=true;$u['badges']=array_values(array_filter(catalogue(),fn($b)=>in_array($b['id'],['bot','official','verified_bot'],true)));saveUser($u);}if(!member($gid,$u['id']))addMember($gid,$u['id']);return $u;
