function botPost(string $gid,?string $cid,string $text,string $kind='moderator',array $attachments=[],?string $key=null,?array $embed=null): ?array {
 if(!$cid)return null;$c=mustEntity($cid,'channel');if($c['groupId']!==$gid||!in_array($c['type'],['text','announcement','forum'],true))fail(400,'Bot channel is invalid.');$u=botAccount($kind,$gid);$id=$key?'bot-msg-'.substr(hash('sha256',$key),0,48):uid();if($m=entity($id,'message'))return visibleMessage($m);
 $msg=putEntity('message',['id'=>$id,'clientId'=>$key,'channelId'=>$cid,'conversationId'=>null,'authorId'=>$u['id'],'content'=>mb_substr($text,0,10000),'type'=>'user','replyToId'=>null,'replyTo'=>null,'pinned'=>false,'editedAt'=>null,'expiresAt'=>null,'deleted'=>false,'attachmentIds'=>$attachments,'reactions'=>[],'mentionedUserIds'=>[],'threadReplyCount'=>0,'poll'=>null,'botEmbed'=>$embed],$cid,$u['id']);foreach($attachments as$aid){$att=mustEntity($aid,'attachment');$att['messageId']=$msg['id'];putEntity('attachment',$att,'',$att['uploaderId']);}emitMessage('channels',$cid,'message:created',$msg);return visibleMessage($msg);
