function botValues(string $gid,string $uid): array {$u=account($uid);$g=mustEntity($gid,'group');return ['username'=>$u['username'],'displayName'=>$u['displayName'],'mention'=>'@'.$u['username'],'userId'=>$uid,'avatar'=>$u['avatarUrl']??'','server'=>$g['name'],'memberCount'=>count(memberIds($gid)),'joinedAt'=>date('c',(int)((member($gid,$uid)['joinedAt']??now())/1000)),'createdAt'=>date('c',(int)($u['createdAt']/1000))];}
function botTemplate(string $text,array $values): string {return preg_replace_callback('/\{([a-zA-Z]+)\}/',fn($m)=>(string)($values[$m[1]]??$m[0]),$text);}
function safeAutomationRole(array $role,bool $self=false): bool {if($role['isDefault']||$role['managed'])return false;$safe=['viewChannel','readMessageHistory','sendMessages','addReactions','attachFiles','embedLinks','useExternalEmojis','useExternalStickers','useApplicationCommands'];return $self?!array_diff($role['permissions'],$safe):!array_intersect($role['permissions'],['administrator','manageGroup','manageRoles','manageChannels','kickMember','banMembers','moderateMembers','manageMembers','manageWebhooks']);}
function automationRole(string $gid,string $uid,string $rid,bool $remove=false,bool $self=false): void {$role=mustEntity($rid,'role');if($role['groupId']!==$gid||!safeAutomationRole($role,$self))fail(403,'Unsafe automation role.');$seat=member($gid,$uid)??fail(404,'Member not found.');$seat['serverRoles']=array_values(array_filter($seat['serverRoles'],fn($r)=>$r['id']!==$rid));if(!$remove)$seat['serverRoles'][]=$role;addMember($gid,$uid,$seat);emitGroup($gid,'group:member-updated',['groupId'=>$gid,'userId'=>$uid]);}
function validateBotSettings(string $gid,array $settings): array {
 $d=decode(file_get_contents(__DIR__.'/bot-defaults.json'));$out=[];
 foreach($d as$section=>$fields){if(!isset($settings[$section])||!is_array($settings[$section]))fail(400,'Missing bot settings section.');$out[$section]=$fields;foreach($settings[$section]as$k=>$v){if(!array_key_exists($k,$fields))fail(400,'Unknown bot setting: '.$k);$default=$fields[$k];if($default!==null&&gettype($v)!==gettype($default))fail(400,'Invalid bot setting type: '.$k);if(is_string($v)&&mb_strlen($v)>3000)fail(400,'Bot text is too long.');if(is_int($v)&&($v<0||$v>2419200))fail(400,'Invalid bot number.');if(is_array($v)&&(!array_is_list($v)||count($v)>100))fail(400,'Invalid bot list.');$out[$section][$k]=$v;}}
