 foreach(['bannerColor','textColor']as$k)if(!preg_match('/^#[a-f0-9]{6}$/iD',$out['welcomer'][$k]))fail(400,'Invalid banner color.');
 foreach($out['welcomer']['autoRoleIds']as$rid)if(!safeAutomationRole(mustEntity($rid,'role')))fail(403,'Unsafe auto role.');foreach($out['moderator']['selfRoleIds']as$rid)if(!safeAutomationRole(mustEntity($rid,'role'),true))fail(403,'Unsafe self role.');
 foreach($out['moderator']['levelRewards']as$r){if(!isset($r['roleId'],$r['level'])||!is_int($r['level'])||$r['level']<1||$r['level']>1000||!safeAutomationRole(mustEntity($r['roleId'],'role')))fail(400,'Invalid XP role reward.');}
 enumValue($out['moderator']['action'],['block','timeout']);foreach($out['moderator']['responses']as$r){required($r,'trigger',120);required($r,'response',2000);if(!is_bool($r['exact']??null))fail(400,'Invalid auto response.');}
 $bg=$out['welcomer']['backgroundAttachmentId'];if($bg){$a=mustEntity($bg,'attachment');$old=botSettings($gid)['settings']['welcomer']['backgroundAttachmentId'];if(($a['uploaderId']!==user()['id']&&$bg!==$old)||!str_starts_with($a['mime'],'image/')||$a['size']>8388608)fail(403,'Invalid banner background.');}return $out;
