function sendWelcome(string $gid,string $uid,string $kind,?string $eventId=null): ?array {
 $s=botSettings($gid)['settings']['welcomer'];if(!$s['enabled'])return null;$cid=$kind==='join'?$s['welcomeChannelId']:$s['goodbyeChannelId'];if(!$cid)return null;$values=botValues($gid,$uid);$text=botTemplate($kind==='join'?$s['welcomeMessage']:$s['goodbyeMessage'],$values);$attachments=[];
 if($s['bannerEnabled']){$png=welcomeBanner($s,$values,$kind);$tmp=tempnam(storageDir(),'banner-');file_put_contents($tmp,$png);try{$bot=botAccount('welcomer',$gid);$att=asUser($bot['id'],fn()=>storeFile($tmp,'welcome.png','image/png'));$attachments[]=$att['id'];}finally{unlink($tmp);}}
 $msg=botPost($gid,$cid,$text,'welcomer',$attachments,$eventId?'welcome-'.$eventId:null);foreach($attachments as$aid){$a=entity($aid,'attachment');$a['messageId']=$msg['id'];putEntity('attachment',$a,'',$a['uploaderId']);}if($kind==='join'&&member($gid,$uid))foreach($s['autoRoleIds']as$rid)automationRole($gid,$uid,$rid);return $msg;
}
function welcomeBanner(array $s,array $v,string $kind): string {
 if(!function_exists('imagecreatetruecolor'))fail(503,'Enable PHP GD to render welcome banners.','provider_not_configured');$im=imagecreatetruecolor(1000,360);$rgb=sscanf($s['bannerColor'],'#%02x%02x%02x');$base=imagecolorallocate($im,...$rgb);imagefill($im,0,0,$base);$bg=$s['backgroundAttachmentId']?entity($s['backgroundAttachmentId'],'attachment'):null;if($bg){$bytes=file_get_contents(storageDir().'/'.$bg['path']);$img=@imagecreatefromstring($bytes);if($img){imagecopyresampled($im,$img,0,0,0,0,1000,360,imagesx($img),imagesy($img));imagedestroy($img);}}
 $textColor=imagecolorallocate($im,...sscanf($s['textColor'],'#%02x%02x%02x'));$shade=imagecolorallocatealpha($im,10,12,24,35);imagefilledrectangle($im,0,0,1000,360,$shade);$title=botTemplate($kind==='join'?$s['bannerTitle']:$s['goodbyeTitle'],$v);$sub=botTemplate($s['bannerSubtitle'],$v);$font=dirname(__DIR__).'/assets/DejaVuSans.ttf';if(function_exists('imagettftext')&&is_file($font)){imagettftext($im,30,0,70,170,$textColor,$font,$title);imagettftext($im,17,0,70,225,$textColor,$font,$sub);}else{imagestring($im,5,70,140,mb_substr($title,0,90),$textColor);imagestring($im,4,70,195,mb_substr($sub,0,110),$textColor);}ob_start();imagepng($im);$png=ob_get_clean();imagedestroy($im);return $png;
}
function membershipBotEvent(string $gid,string $uid,string $kind): void {
 $event=putEntity('bot_event',['groupId'=>$gid,'userId'=>$uid,'eventKind'=>$kind,'done'=>false,'attempts'=>0],$gid,$uid);try{sendWelcome($gid,$uid,$kind,$event['id']);$event['done']=true;}catch(Throwable $e){$event['attempts']++;$event['error']=$e->getMessage();}putEntity('bot_event',$event,$gid,$uid);
