function inspectBuiltinMessage(array $c,string $uid,string $text,int $attachmentCount=0): void {
 $s=botSettings($c['groupId'])['settings']['moderator'];$u=account($uid);if(!$s['enabled']||($u['builtinBot']??false)||groupCan($c['groupId'],'deleteAnyMessage',$uid)||in_array($c['id'],$s['exemptChannelIds'],true)||array_intersect(array_column(memberServerRoles($c['groupId'],$uid),'id'),$s['exemptRoleIds']))return;
