 if($reason){if($s['action']==='timeout'){$seat=member($c['groupId'],$uid);$seat['timeoutUntil']=now()+$s['timeoutSeconds']*1000;addMember($c['groupId'],$uid,$seat);}recordBotCase($c['groupId'],$uid,'automod',$reason);fail(403,'Moderator: '.$reason);}
